  govern: [ transaction ]
  next: rejectDuplicateHousehold

rejectDuplicateHousehold:
  class: org.springframework.samples.petclinic.rest.function.owner.RejectDuplicateOwnerHousehold
  govern: [ transaction ]
  next: normalizeEmail

