- `rest/function/owner/NormalizeOwnerAddress.java`, `ValidateRequiredOwnerFields.java`, `RejectDailyOwnerLimit.java`, `RejectFullOwnerCity.java`, `NormalizeOwnerTelephone.java`, `RejectDuplicateOwnerTelephone.java`, `RejectDuplicateOwnerHousehold.java`, `NormalizeOwnerEmail.java`, `BuildOwner.java`, `AssignOwnerNamesakeCount.java`, `DefaultOwnerRegistrationDate.java`, `AssignOwnerCustomerCode.java`, `AssignOwnerHousehold.java`, `SaveOwner.java`, `RespondWithOwnerCreated.java`
